void dei_rs_gwr( void )
{	
	set_rs_gwr( TRUE ); 
	
	set_rs_idle( get_ign_status() );
						
	set_rs_retry_count( get_rs_idle() ? 2 : 0 );
    
    cmd_q_rs_insert( INPUT_GWR_ON , 100 );
	
	dei_prk_flash( (get_rs_mts_progress() || get_rs_turbo()) ? DEI_PRK_MTS_ON : DEI_PRK_RS_CONFIRM ); 
						
	ATOMIC( dei_rs_state = (Dei_Rs_State)dei_rs_acc );

	dei_rs_secure_lock_gwr_on();
}

